type DefineProductPriceOperation = Extract<ManageProductPriceOperation, { readonly kind: 'DEFINE_PRICE' }>;
type ReviseProductPriceOperation = Extract<ManageProductPriceOperation, { readonly kind: 'REVISE_PRICE' }>;

const pricePortFailure = (code: string, cause?: unknown): ProductPriceBulkPortFailure =>
  cause === undefined
    ? { _tag: 'ProductPriceBulkPortFailure', code }
    : { _tag: 'ProductPriceBulkPortFailure', cause, code };

const canonicalPrice = (definition: {
  readonly priceRef: ProductPriceBulkCanonicalRefs['priceRef'];
  readonly revision: { readonly revisionId: string };
}) => ({ priceRef: definition.priceRef, revisionId: definition.revision.revisionId });

const samePriceIdentity = Schema.toEquivalence(PriceIdentityKeySchema);
const samePriceRef = (
  left: ProductPriceBulkCanonicalRefs['priceRef'],
  right: ProductPriceBulkCanonicalRefs['priceRef'],
): boolean =>
  left.moduleId === right.moduleId &&
  left.resourceId === right.resourceId &&
  left.resourceType === right.resourceType &&
  left.tenantId === right.tenantId;

const priceResultMatchesOperation = (
  operation: ManageProductPriceOperation,
  target: PriceProductTargetOutcomeIdentity['target'],
  result: Extract<PriceActionResultLookupOutcome, { readonly outcome: 'PRICE_ACTION_RESULT_FOUND' }>['result'],
): boolean => {
  if (operation.kind === 'DEFINE_PRICE') {
    return (
      (result.outcome === 'CREATED' || result.outcome === 'REUSED') &&
      priceCatalogTargetsEqual(result.definition.identityKey.catalogSelection, target) &&
      samePriceRef(result.definition.priceRef, operation.payload.priceRef) &&
      samePriceIdentity(result.definition.identityKey, operation.payload.identityKey) &&
      result.definition.revision.effectiveFrom === operation.payload.effectiveFrom &&
      result.definition.revision.monetaryAmount.currencyCode === operation.payload.monetaryAmount.currencyCode &&
      priceDecimalValuesEqual(result.definition.revision.monetaryAmount.amount, operation.payload.monetaryAmount.amount)
    );
  }
  if (result.outcome !== 'REVISED' && result.outcome !== 'UNCHANGED') {
    return false;
  }
  if (
    !priceCatalogTargetsEqual(result.revision.definition.identityKey.catalogSelection, target) ||
    !samePriceRef(result.revision.definition.priceRef, operation.payload.priceRef)
  ) {
    return false;
  }
  if (operation.payload.intent === 'RETIRE_CURRENT') {
    return true;
  }
  return (
    result.revision.definition.revision.monetaryAmount.currencyCode === operation.payload.monetaryAmount.currencyCode &&
    priceDecimalValuesEqual(
      result.revision.definition.revision.monetaryAmount.amount,
      operation.payload.monetaryAmount.amount,
    )
  );
};

const ownerOutcomeFromPriceResult = (
  command: ProductPriceBulkCommand<ManageProductPriceOperation>,
  result: Extract<PriceActionResultLookupOutcome, { readonly outcome: 'PRICE_ACTION_RESULT_FOUND' }>['result'],
): ProductPriceBulkOwnerOutcome => {
  if (!priceResultMatchesOperation(command.operation, command.identity.target, result)) {
    return { outcome: 'CONFLICT', reasonCode: 'IDEMPOTENCY_CONFLICT' };
  }
  if (result.outcome === 'CREATED' || result.outcome === 'REUSED') {
    return {
      canonical: canonicalPrice(result.definition),
      outcome: result.outcome === 'CREATED' ? 'APPLIED' : 'UNCHANGED',
    };
  }
  if (result.outcome === 'REVISED' || result.outcome === 'UNCHANGED') {
    return {
      canonical: canonicalPrice(result.revision.definition),
      outcome: result.outcome === 'REVISED' ? 'APPLIED' : 'UNCHANGED',
    };
  }
  if (result.outcome === 'CONFLICT') {
    return { outcome: 'CONFLICT', reasonCode: result.reason };
  }
  if (result.outcome === 'ACKNOWLEDGEMENT_REQUIRED') {
    return { outcome: 'REJECTED', reasonCode: 'PRICE_SCHEDULE_ACKNOWLEDGEMENT_REQUIRED' };
  }
  return { outcome: 'REJECTED', reasonCode: 'PRICE_SCHEDULE_ABSENT' };
};

const reconcilePriceTarget = (
  persistence: TransactionScopedPricePersistence,
  command: ProductPriceBulkCommand<ManageProductPriceOperation>,
  actionInvocationId: string,
) =>
  persistence.lookupResult({ actionInvocationId }).pipe(
    Effect.map((lookup) =>
      lookup.outcome === 'PRICE_ACTION_RESULT_FOUND'
        ? ({ outcome: ownerOutcomeFromPriceResult(command, lookup.result), status: 'RESOLVED' as const } as const)
        : ({ status: 'RETRY_ALLOWED' as const } as const),
    ),
    Effect.mapError((cause) => pricePortFailure('PriceOwnerResultLookupUnavailable', cause)),
  );

const priceCommandTrusted = (
  command: ProductPriceBulkCommand<ManageProductPriceOperation>,
  actionInvocationId: string,
) => ({
  actingPrincipalId: command.trusted.principalContext.principalId,
  actionInvocationId,
  legalEntityId: command.trusted.principalContext.legalEntityId,
  requestCorrelationId: command.targetCorrelationRef,
  tenantId: command.trusted.principalContext.tenantId,
  trustedOperationAt: command.trusted.trustedOperationAt,
});

const rejectedPriceOutcome = (reasonCode: string): ProductPriceBulkOwnerOutcome => ({
  outcome: 'REJECTED',
  reasonCode,
});

const handleDefinePriceRejected = (error: DefinePriceRejected) => Effect.succeed(rejectedPriceOutcome(error.code));

const handleRevisePriceConflict = (error: RevisePriceConflict) =>
  Effect.succeed({ outcome: 'CONFLICT' as const, reasonCode: error.reason });

const handleRevisePriceRejected = (error: RevisePriceRejected) => Effect.succeed(rejectedPriceOutcome(error.code));

const handleRevisePriceSourceDependencyUnavailable = (error: RevisePriceSourceDependencyUnavailable) =>
  Effect.fail(pricePortFailure(`Price${error.dependency}Unavailable`, error));

const handleRevisePriceSourceHeld = (error: RevisePriceSourceHeld) =>
  Effect.succeed(rejectedPriceOutcome(`${error.outcome}:${error.reason}`));

const handleRevisePriceSourceInvalid = (error: RevisePriceSourceInvalid) =>
  Effect.succeed(rejectedPriceOutcome(`${error.outcome}:${error.reason}`));

const executePriceDefinition = (
  command: ProductPriceBulkCommand<ManageProductPriceOperation>,
  operation: DefineProductPriceOperation,
  actionInvocationId: string,
  options: ProductPriceBulkCommandOptions,
) =>
  applyPriceDefinition(
    operation.payload,
    priceCommandTrusted(command, actionInvocationId),
    options.defineServices,
  ).pipe(
    Effect.catchTags({
      DefinePriceRejected: handleDefinePriceRejected,
      PricePersistenceUnavailable: (cause: unknown) =>
        Effect.fail(pricePortFailure('PricePersistenceUnavailable', cause)),
    }),
    Effect.flatMap((result) => {
      if ('reasonCode' in result) {
        return Effect.succeed(result);
      }
      if (result.outcome === 'PRICE_SOURCE_ASSERTION_CANONICAL_ACCEPTED') {
        return reconcilePriceTarget(options.persistence, command, actionInvocationId).pipe(
          Effect.flatMap((reconciliation) =>
            reconciliation.status === 'RESOLVED'
              ? Effect.succeed(reconciliation.outcome)
              : Effect.fail(pricePortFailure('PriceOwnerResultReceiptMissing')),
          ),
        );
      }
      if (result.outcome === 'PRICE_SOURCE_ASSERTION_DEPENDENCY_UNAVAILABLE') {
        return Effect.fail(pricePortFailure(`Price${result.dependency}Unavailable`));
      }
      return 'reason' in result
        ? Effect.succeed(rejectedPriceOutcome(`${result.outcome}:${result.reason}`))
        : Effect.fail(pricePortFailure('PriceOwnerOutcomeUnrecognized'));
    }),
  );

const verifyRevisedPriceTarget = (
  command: ProductPriceBulkCommand<ManageProductPriceOperation>,
  operation: ReviseProductPriceOperation,
  persistence: TransactionScopedPricePersistence,
): Effect.Effect<
  { readonly outcome: ProductPriceBulkOwnerOutcome; readonly status: 'BLOCKED' } | { readonly status: 'VERIFIED' },
  ProductPriceBulkPortFailure
> =>
  persistence.readSchedule(operation.payload.priceRef, command.trusted.trustedOperationAt).pipe(
    Effect.map((result) => {
      if (result.outcome === 'PRICE_SCHEDULE_ABSENT') {
        return { outcome: rejectedPriceOutcome('PRICE_SCHEDULE_ABSENT'), status: 'BLOCKED' } as const;
      }
      if (result.outcome === 'PRICE_SCHEDULE_CONFLICT') {
        return {
          outcome: { outcome: 'CONFLICT', reasonCode: result.outcome },
          status: 'BLOCKED',
        } as const;
      }
      return result.schedule.revisions.every(({ definition }) =>
        priceCatalogTargetsEqual(definition.identityKey.catalogSelection, command.identity.target),
      )
        ? ({ status: 'VERIFIED' } as const)
        : ({ outcome: rejectedPriceOutcome('PRICE_TARGET_SNAPSHOT_MISMATCH'), status: 'BLOCKED' } as const);
    }),
    Effect.mapError((cause) => pricePortFailure('PricePersistenceUnavailable', cause)),
  );

const executePriceRevision = Effect.fn('ProductPriceBulkService.executePriceRevision')(function* executePriceRevision(
  command: ProductPriceBulkCommand<ManageProductPriceOperation>,
  operation: ReviseProductPriceOperation,
  actionInvocationId: string,
  options: ProductPriceBulkCommandOptions,
) {
  const targetFailure = yield* verifyRevisedPriceTarget(command, operation, options.persistence);
  if (targetFailure.status === 'BLOCKED') {
    return targetFailure.outcome;
  }
  return yield* applyPriceRevision(
    operation.payload,
    priceCommandTrusted(command, actionInvocationId),
    options.reviseServices,
  ).pipe(
    Effect.map((result): ProductPriceBulkOwnerOutcome => ({
      canonical: canonicalPrice(result.revision.definition),
      outcome: result.outcome === 'PRICE_REVISION_CREATED' ? 'APPLIED' : 'UNCHANGED',
    })),
    Effect.catchTags({
      PricePersistenceUnavailable: (cause: unknown) =>
        Effect.fail(pricePortFailure('PricePersistenceUnavailable', cause)),
      RevisePriceAcknowledgementRequired: () =>
        Effect.succeed(rejectedPriceOutcome('PRICE_SCHEDULE_ACKNOWLEDGEMENT_REQUIRED')),
      RevisePriceConflict: handleRevisePriceConflict,
      RevisePriceRejected: handleRevisePriceRejected,
      RevisePriceSourceDependencyUnavailable: handleRevisePriceSourceDependencyUnavailable,
      RevisePriceSourceHeld: handleRevisePriceSourceHeld,
      RevisePriceSourceInvalid: handleRevisePriceSourceInvalid,
    }),
  );
});

export const makeProductPriceBulkCommandPort = (
  options: ProductPriceBulkCommandOptions,
): ProductPriceBulkCommandPort<ManageProductPriceOperation> =>
  productPriceBulkCommandExecution({
    executeAuthorizedExactPriceAction: (command) => {
      const actionInvocationId = productPriceBulkActionInvocationIdFor(
        command.trusted.principalContext.tenantId,
        command.intentId,
      );
      const { operation } = command;
      return operation.kind === 'DEFINE_PRICE'
        ? executePriceDefinition(command, operation, actionInvocationId, options)
        : executePriceRevision(command, operation, actionInvocationId, options);
    },
    reconcileAuthorizedExactPriceAction: (command) =>
      reconcilePriceTarget(
        options.persistence,
        command,
        productPriceBulkActionInvocationIdFor(command.trusted.principalContext.tenantId, command.intentId),
      ),
  });

export const productPriceBulkServiceForScope: ReadServiceFactory<
  ProductPriceBulkService<ManageProductPriceOperation>,
  ExternalPriceInputBoundaryFactory
> = Effect.fn('ProductPriceBulkService.productPriceBulkServiceForScope')(
  function* makeProductPriceBulkServices(transaction, scope) {
    const { legalEntityId } = scope;
    if (legalEntityId === undefined) {
      return yield* new OperationContextUnavailable({
        code: 'operation_context_unavailable',
        reason: 'Product Price bulk management requires a trusted Selling Legal Entity',
      });
    }
    const externalPriceInputBoundaryFactory = yield* ExternalPriceInputBoundaryFactory;
    const { authority, catalog, commercialContext, currencySupport, persistence } = yield* Effect.all(
      {
        authority: externalPriceSourceAuthorityForScope(transaction, scope),
        catalog: catalogSelectionAssessmentPortFromEnvironment({
          legalEntityId,
          requestCorrelation: scope.correlationId,
        }),
        commercialContext: commercialContextAssessmentPortFromEnvironment({
          legalEntityId,
          requestCorrelation: scope.correlationId,
        }),
        currencySupport: currencySupportPersistenceForScope(transaction, scope),
        persistence: pricePersistenceForScope(transaction, scope),
      },
      { concurrency: 5 },
    );
    const externalPriceInputBoundary = externalPriceInputBoundaryFactory.make(authority);
    const options: ProductPriceBulkCommandOptions = {
      defineServices: {
        assessCatalogSelection: catalog.assess,
        assessCommercialContext: commercialContext.assess,
        assessExternalPriceInput: externalPriceInputBoundary.assess,
        define: persistence.define,
        loadCurrencySupport: currencySupport.loadCurrent,
      },
      persistence,
      reviseServices: {
        assessExternalPriceInput: externalPriceInputBoundary.assess,
        readSchedule: persistence.readSchedule,
        revise: persistence.revise,
      },
    };
    return ProductPriceBulk.of(makeProductPriceBulkService(makeProductPriceBulkCommandPort(options)));
  },
);
